-- Additive Market Updates multi-source ingestion, health, run ledger and dedupe contracts.
create extension if not exists pgcrypto;
alter table public.market_sources
 add column if not exists source_key text,
 add column if not exists adapter_type text,
 add column if not exists primary_url text,
 add column if not exists feed_urls jsonb not null default '[]',
 add column if not exists listing_urls jsonb not null default '[]',
 add column if not exists adapter_config jsonb not null default '{}',
 add column if not exists source_authority text,
 add column if not exists perspective text,
 add column if not exists copyright_mode text,
 add column if not exists extraction_policy jsonb not null default '{"metadata_only":true,"full_article":false}',
 add column if not exists source_weight numeric not null default 1,
 add column if not exists refresh_frequency_minutes integer not null default 60,
 add column if not exists consecutive_failures integer not null default 0,
 add column if not exists health_status text not null default 'degraded',
 add column if not exists last_http_status integer,
 add column if not exists last_latency_ms integer,
 add column if not exists last_items_discovered integer not null default 0,
 add column if not exists last_items_published integer not null default 0,
 add column if not exists last_etag text,
 add column if not exists last_modified text,
 add column if not exists next_cursor text,
 add column if not exists disabled_reason text,
 add column if not exists terms_review_status text not null default 'pending',
 add column if not exists terms_reviewed_at timestamptz,
 add column if not exists default_segments jsonb not null default '[]';
create unique index if not exists market_sources_source_key_uidx on public.market_sources(source_key) where source_key is not null;
alter table public.market_sources drop constraint if exists market_sources_health_status_check;
alter table public.market_sources add constraint market_sources_health_status_check check(health_status in ('healthy','degraded','failed','disabled')) not valid;

create table if not exists public.market_ingestion_runs (
 id uuid primary key default gen_random_uuid(), trigger_type text not null check(trigger_type in ('cron','page_open','manual','digest_prerequisite','retry','source_test')), requested_by uuid, started_at timestamptz not null default now(), completed_at timestamptz, status text not null default 'queued' check(status in ('queued','running','completed','partial','failed','skipped_fresh')), sources_considered int not null default 0, sources_processed int not null default 0, sources_succeeded int not null default 0, sources_failed int not null default 0, items_discovered int not null default 0, items_deduplicated int not null default 0, items_classified int not null default 0, items_published int not null default 0, items_candidate int not null default 0, items_ignored int not null default 0, duration_ms int, error_summary text, metadata jsonb not null default '{}'
);
create table if not exists public.market_source_fetch_runs (
 id uuid primary key default gen_random_uuid(), ingestion_run_id uuid not null references public.market_ingestion_runs(id) on delete cascade, source_id uuid not null references public.market_sources(id) on delete cascade, started_at timestamptz not null default now(), completed_at timestamptz, status text not null, http_status int, adapter_used text, feed_url_used text, latency_ms int, items_discovered int not null default 0, items_published int not null default 0, consecutive_failure_count int not null default 0, safe_error_message text
);
alter table public.market_updates
 add column if not exists external_id text,
 add column if not exists canonical_url text,
 add column if not exists original_url text,
 add column if not exists source_authority text,
 add column if not exists source_perspective text,
 add column if not exists author text,
 add column if not exists public_excerpt text,
 add column if not exists legal_status text not null default 'not_applicable',
 add column if not exists effective_date date,
 add column if not exists royal_assent_date date,
 add column if not exists commencement_date date,
 add column if not exists bill_status text,
 add column if not exists lender_name text,
 add column if not exists policy_effective_date date,
 add column if not exists affected_borrower_types jsonb not null default '[]',
 add column if not exists affected_security_types jsonb not null default '[]',
 add column if not exists lending_criteria_tags jsonb not null default '[]',
 add column if not exists legal_topics jsonb not null default '[]',
 add column if not exists economic_topics jsonb not null default '[]',
 add column if not exists source_payload_hash text,
 add column if not exists classification_version text,
 add column if not exists summarisation_version text,
 add column if not exists model_used text,
 add column if not exists verified_against_primary_source boolean not null default false,
 add column if not exists primary_source_urls jsonb not null default '[]';
create unique index if not exists market_updates_source_external_uidx on public.market_updates(source_id,external_id) where external_id is not null;
create unique index if not exists market_updates_canonical_uidx on public.market_updates(canonical_url) where canonical_url is not null;
create index if not exists market_updates_segments_gin on public.market_updates using gin(segments);
create index if not exists market_updates_lending_tags_gin on public.market_updates using gin(lending_criteria_tags);
create index if not exists market_updates_legal_status_idx on public.market_updates(legal_status);
create index if not exists market_ingestion_runs_status_idx on public.market_ingestion_runs(status,started_at desc);
create index if not exists market_source_fetch_runs_source_idx on public.market_source_fetch_runs(source_id,started_at desc);
alter table public.market_ingestion_runs enable row level security; alter table public.market_source_fetch_runs enable row level security;
grant select on public.market_ingestion_runs to authenticated; grant all on public.market_ingestion_runs to service_role;
grant select on public.market_source_fetch_runs to authenticated; grant all on public.market_source_fetch_runs to service_role;
drop policy if exists "Authenticated users read sanitised ingestion status" on public.market_ingestion_runs;
create policy "Authenticated users read sanitised ingestion status" on public.market_ingestion_runs for select to authenticated using(true);
drop policy if exists "Authenticated users read source fetch status" on public.market_source_fetch_runs;
create policy "Authenticated users read source fetch status" on public.market_source_fetch_runs for select to authenticated using(true);

-- Database-backed single-flight acquisition. Service role only.
create or replace function public.acquire_market_ingestion_run(p_trigger text,p_requested_by uuid default null,p_timeout_seconds int default 240)
returns public.market_ingestion_runs language plpgsql security definer set search_path=public as $$ declare active public.market_ingestion_runs; created public.market_ingestion_runs; begin
 perform pg_advisory_xact_lock(hashtext('market-updates-ingestion'));
 select * into active from public.market_ingestion_runs where status in ('queued','running') and started_at > now()-make_interval(secs=>p_timeout_seconds) order by started_at desc limit 1;
 if active.id is not null then active.metadata := coalesce(active.metadata,'{}'::jsonb)||'{"single_flight_reused":true}'::jsonb; return active; end if;
 update public.market_ingestion_runs set status='failed',completed_at=now(),error_summary='Timed out before completion' where status in ('queued','running');
 insert into public.market_ingestion_runs(trigger_type,requested_by,status) values(p_trigger,p_requested_by,'running') returning * into created; return created;
end $$;
revoke all on function public.acquire_market_ingestion_run(text,uuid,int) from public,anon,authenticated; grant execute on function public.acquire_market_ingestion_run(text,uuid,int) to service_role;

