insert into public.market_sources(source_key,name,description,source_type,url,category,geography,reliability_tier,enabled,refresh_frequency_hours,adapter_type,primary_url,feed_urls,listing_urls,source_authority,default_segments,refresh_frequency_minutes,copyright_mode,perspective,adapter_config,extraction_policy) select source_key,name,description,adapter_type,primary_url,category,'Australia',reliability_tier,true,greatest(1,ceil(refresh_frequency_minutes/60.0)::int),adapter_type,primary_url,feed_urls,listing_urls,source_authority,default_segments,refresh_frequency_minutes,copyright_mode,perspective,'{"item_selector":"article","title_selector":"h2,h3","link_selector":"a[href]","date_selector":"time","excerpt_selector":"p"}','{"metadata_only":true,"full_article":false}' from registry on conflict(source_key) where source_key is not null do update set name=excluded.name,description=excluded.description,adapter_type=excluded.adapter_type,primary_url=excluded.primary_url,feed_urls=excluded.feed_urls,listing_urls=excluded.listing_urls,source_authority=excluded.source_authority,reliability_tier=excluded.reliability_tier,default_segments=excluded.default_segments,category=excluded.category,refresh_frequency_minutes=excluded.refresh_frequency_minutes,copyright_mode=excluded.copyright_mode,perspective=excluded.perspective,updated_at=now();
-- Hourly scheduling follows the existing pg_cron/pg_net + Vault secret convention.
do $$ begin if exists(select 1 from pg_extension where extname='pg_cron') then perform cron.unschedule(jobid) from cron.job where jobname='market-updates-hourly'; perform cron.schedule('market-updates-hourly','5 * * * *',$job$select net.http_post(url := current_setting('app.settings.supabase_url',true)||'/functions/v1/market-updates-ingest',headers := jsonb_build_object('content-type','application/json','x-cron-secret',current_setting('app.settings.market_ingestion_cron_secret',true)),body := '{"trigger_type":"cron"}'::jsonb);$job$); end if; end $$;
